return {["Sheet1"]={["task1"]={["btnName1"]=[[翻过此页]],["finishCondition"]=5000,["id"]=[[task1]],["isEnd"]=0,["nextTaskId1"]=[[task2]],["storyText"]=[[你按照笔录上的指示，将笔录翻到对应的书页，只见书页上写着几行字：]],["targetText"]=[[任务目标：提升自我等级达到30级]],["taskText"]=[[江南烟雨美人骨，漠上日圆骆铃轻。老夫年少时，见过厉害的侠客只用一兵一马，仗着自身本领行走大江南北，见识天地广阔。
